export function validateLetter({signature,title,body}){for(const [key,min,max] of [['signature',2,80],['title',8,180],['body',80,8000]]){const s=String({signature,title,body}[key]||'').trim();if(s.length<min||s.length>max)throw Error({signature:'La firma debe tener entre 2 y 80 caracteres.',title:'El título debe tener entre 8 y 180 caracteres.',body:'La carta debe tener entre 80 y 8.000 caracteres.'}[key]);}return {signature:signature.trim(),title:title.trim(),body:body.trim()};}
export function initLetters({db,esc,date,login}){
 const root=document.getElementById('cartas');let user=null,rows=[],limit=20,version=0;
 root.innerHTML=`<div class="heading"><div><span class="eyebrow">OPINIÓN / CONVERGENCIA AURA</span><h1>Cartas al director.</h1><p>Una mirada personal puede abrir una conversación pública.</p></div><button class="primary" id="write-letter">＋ Escribir una carta</button></div><div class="letters-layout"><div><div class="letters-tools"><label>Buscar cartas<input id="letters-search" type="search" placeholder="Título, firma o contenido"></label><button id="letters-refresh">↻ Actualizar</button></div><p id="letters-status" role="status"></p><div id="letters-list"></div><button id="letters-more" hidden>Ver más cartas</button></div><aside class="panel"><span class="eyebrow">TRIBUNA ABIERTA</span><h2>Tu voz, en tus palabras.</h2><p>Publicación directa con tu cuenta de Convergencia. Las cartas expresan la opinión de quienes las firman; no son noticias verificadas ni la postura editorial de Atlas.</p><p>Comparte argumentos y contexto. Evita divulgar datos personales de terceros.</p><p>Tu firma y el texto serán públicos. Puedes retirar tus cartas desde tu cuenta.</p></aside></div>`;
 const $=id=>document.getElementById(id),dialog=document.createElement('dialog');dialog.className='letter-dialog';dialog.innerHTML='<button class="close" aria-label="Cerrar carta">×</button><h2>Escribir al director</h2><form id="letter-form"><label>Firma pública<input name="signature" required minlength="2" maxlength="80" autocomplete="nickname"></label><label>Título<input name="title" required minlength="8" maxlength="180"></label><label>Tu carta<textarea name="body" required minlength="80" maxlength="8000" rows="12"></textarea></label><p>Se publicará directamente y será visible para todos.</p><button class="primary" type="submit">Publicar carta</button><p role="status" id="letter-submit-status"></p></form>';document.body.append(dialog);dialog.querySelector('.close').onclick=()=>dialog.close();
 $('write-letter').onclick=()=>{if(!user){login();return;}dialog.showModal();};
 function render(){const q=$('letters-search').value.toLocaleLowerCase();$('letters-list').innerHTML=rows.filter(r=>[r.title,r.signature,r.body].join(' ').toLocaleLowerCase().includes(q)).map(r=>`<article class="letter-card"><span class="eyebrow">CARTA AL DIRECTOR · OPINIÓN</span><h2>${esc(r.title)}</h2><p class="letter-byline">${esc(r.signature)} · ${esc(date(r.created_at))}</p><div class="letter-text">${esc(r.body)}</div>${r.owner_id===user?.id?`<button data-withdraw="${r.id}">Retirar mi carta</button>`:''}</article>`).join('')||'<div class="empty"><h2>Una conversación por comenzar.</h2><p>No hay cartas publicadas que coincidan con esta búsqueda.</p></div>';
 root.querySelectorAll('[data-withdraw]').forEach(b=>b.onclick=async()=>{if(!confirm('¿Retirar esta carta de la publicación?'))return;b.disabled=true;const {error}=await db.from('atlas_dev_letters').delete().eq('id',b.dataset.withdraw).eq('owner_id',user.id);if(error){$('letters-status').textContent='No se pudo retirar la carta.';b.disabled=false;}else load();});}
 async function load(){const v=++version;$('letters-status').textContent='Cargando cartas…';try{if(!db)throw Error();const {data,error}=await db.from('atlas_dev_letters').select('*').order('created_at',{ascending:false}).limit(limit);if(error)throw error;if(v!==version)return;rows=data;render();$('letters-more').hidden=data.length<limit;$('letters-status').textContent=`${data.length} cartas cargadas`;}catch{if(v===version)$('letters-status').textContent='No se pudieron cargar las cartas. Pulsa Actualizar para reintentar.';}}
 dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();if(!user)return;const button=e.target.querySelector('[type=submit]');try{const data=validateLetter(Object.fromEntries(new FormData(e.target)));button.disabled=true;$('letter-submit-status').textContent='Publicando…';const {error}=await db.from('atlas_dev_letters').insert(data);if(error)throw error;e.target.reset();dialog.close();await load();}catch(error){$('letter-submit-status').textContent=error.message||'No se pudo publicar. Tu texto se conserva.';}finally{button.disabled=false;}};
 $('letters-search').oninput=render;$('letters-refresh').onclick=load;$('letters-more').onclick=()=>{limit+=20;load()};
 function auth(session){if(user?.id!==session?.user?.id){dialog.close();dialog.querySelector('form').reset();}user=session?.user||null;render();}
 db?.auth.getSession().then(({data})=>auth(data.session));db?.auth.onAuthStateChange((_event,s)=>setTimeout(()=>auth(s),0));load();return {refresh:load};
}
